import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import re

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_filename(filename):
    """Remove path traversal attempts but preserve extension"""
    name = secure_filename(filename)
    if not name:
        name = 'unnamed_document.txt'
    return name

def compute_job_id(content):
    return hashlib.sha256(content).hexdigest()[:16]

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

@app.route('/api/v1/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if uploaded.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(uploaded.filename):
        return jsonify({'error': 'File type not allowed'}), 415

    output_format = request.form.get('format', 'pdf')
    # Validate output format
    if not re.match(r'^[a-z]{2,4}$', output_format):
        return jsonify({'error': 'Invalid output format'}), 400

    safe_name = sanitize_filename(uploaded.filename)
    content = uploaded.read()
    job_id = compute_job_id(content)

    work_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(work_dir, exist_ok=True)

    input_path = os.path.join(work_dir, safe_name)
    with open(input_path, 'wb') as f:
        f.write(content)

    # Additional conversion options from user
    extra_args = request.form.get('libreoffice_args', '')

    # Build conversion command
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {work_dir} {input_path} {extra_args}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=work_dir
        )
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timeout'}), 504

    if result.returncode != 0:
        return jsonify({
            'error': 'Conversion failed',
            'detail': result.stderr.decode('utf-8', errors='replace')[:200]
        }), 500

    # Find output file
    base_name = os.path.splitext(safe_name)[0]
    output_path = os.path.join(work_dir, f'{base_name}.{output_format}')

    if not os.path.exists(output_path):
        return jsonify({'error': 'Output file not generated'}), 500

    return send_file(
        output_path,
        as_attachment=True,
        download_name=f'{base_name}.{output_format}'
    )

@app.route('/api/v1/batch', methods=['POST'])
def batch_status():
    """Check batch conversion status"""
    job_ids = request.json.get('job_ids', [])
    results = {}
    for jid in job_ids:
        # Prevent directory traversal in job_id lookup
        if not re.match(r'^[a-f0-9]{16}$', jid):
            continue
        path = os.path.join(UPLOAD_DIR, jid)
        results[jid] = os.path.isdir(path)
    return jsonify(results)

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
